INSERT INTO QueryTypes (uuid, created_at, last_updated_at, deleted_at, name, description, is_customized, is_available)
VALUES
('7c61bee6-aef7-4ccf-9184-eb285bbeee14', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '射覆', '所谓“射覆”，就是在瓯、盂等器具下覆盖某一物件，让人猜测里面是什么东西。', 0, 1),
('b07421dc-6ef5-4959-afd3-7c618b152fb4', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '命理', '通过分析生辰八字（出生年、月、日、时）或出生时间以及出生地点推测人生轨迹的学问，核心是阴阳五行、天干地支的相互作用，用于预测性格、事业、婚姻等。', 0, 1),
('6c4cd644-284c-4eb0-bc76-615ce5d6dc04', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '运程', '指特定时间段的运势走势，包括十年大运、流年等周期，强调动态变化与个人选择对命运的影响，如“命定运改”。', 0, 1),
('17a4240b-8391-40b6-9fa5-4cd154b9413c', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '占测', '泛指通过术数预测未来的行为，如六爻、奇门遁甲、六爻等，用于解答具体问题或趋吉避凶。', 0, 1),
('25957593-9430-4176-8f91-577815a69df4', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '择吉', '选择有利时间与方位的方法，结合干支历法、神煞系统（如黄道吉日）及风水理论，用于婚嫁、动土等重大事项。选择最佳的行动时间，以尽可能达到预期的结果', 0, 1),
('11379e76-40a8-4c78-a470-8270ae231fd4', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '堪舆', '研究环境与人的关系，通过山水布局、建筑方位等调整气场，核心是“藏风聚气”，分阳宅（住宅）与阴宅（墓葬）。', 0, 1),
('32ba19c0-67fa-4a5c-b91a-7fc1046a40e4', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '化解', '针对不利因素（如煞气、命理冲突、突发灾厄）的调整方法，包括风水布局、修行提高、行为禁忌等，旨在转凶为吉。', 0, 1),
('1c7f826d-346d-4222-858d-211678c927e5', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '运筹', '资源统筹与决策优化的科学，运用数学模型（如线性规划）解决复杂问题，现代应用于管理、军事等领域。', 0, 1);
('ab385997-1890-43f3-8a6d-b6236ad1ab37', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '合婚', '中国传统命理学中的婚姻配对方法，通过分析男女双方的生辰，评估两人在五行、生肖、神煞等方面的契合度，预测婚姻吉凶，以及婚后子嗣等情况', 0, 1);
('f6d79a52-bb4d-4a14-a3f7-f1e273e7be5b', '2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, '合盘', '传统命理数术，两人或多人的生辰来预测，商业合作，合同签订的顺利程度，帮助合伙人进行更好的商业决策，如根据合伙人各自不同的天赋进行分工', 0, 1);
