INSERT INTO Skills (created_at, last_updated_at, deleted_at, is_available, name, descriptions)
VALUES
(1,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '奇门遁甲', '上古三式之一，奇门遁甲是中国古代术数体系，综合了天文、地理、兵法等多方面知识，用于预测和决策。'),
(2,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '大六壬', '上古三式之一，大六壬以占卜人事著称，通过课式来推断事物发展变化。'),
(3,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '太乙神数', '上古三式之一，太乙神数是古代高层次预测学，被称为帝王之术，用于预测国家政治、军事等大事。'),
(4,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '四柱八字', '四柱八字以人出生的年、月、日、时为基础，通过天干地支组合成八字，来推算人的命运。'),
(5,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '禄命法', '禄命法以人的出生年、月、日所值干支来推算人的禄命，判断人的贵贱贫富、寿夭祸福。'),
(6,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '紫微斗数', '紫微斗数是一种星命术，以人的出生年、月、日、时确定十二宫的位置，结合星曜来预测人生运势。'),
(7,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '七政四余', '七政四余是中国古代占星学，通过对日月和五大行星以及罗睺、计都、紫炁、月孛的运行规律来推断人的命运。'),
(8,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '演禽术', '演禽术是一种以十二种动物命名神煞，通过它们的生克关系来预测人事吉凶的术数。'),
(9,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '梅花易数', '梅花易数是一种简易的占卜方法，通过随机事物起卦，以《易经》为基础进行占断。'),
(10,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '六爻', '六爻是利用三枚铜钱摇卦，根据所得卦象来预测事物发展变化的占卜方法。'),
(11,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '小六壬', '小六壬是一种简便的占卜方式，通过月、日、时的组合来快速判断事情的吉凶。'),
(12,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '周易', '《周易》是中国传统思想文化中自然哲学与人文实践的理论根源，可用于哲学思考、占卜预测等。'),
(13,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '太玄经', '《太玄经》是模仿《周易》而作的一部哲学著作，也可用于占卜等方面。'),
(14,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '京房易', '京房易是西汉京房所创的易学流派，将《周易》与阴阳五行相结合，用于占卜和预测。'),
(15,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '铁板神数', '铁板神数是一种以生辰八字为基础，结合特定规则来推算人的命运、六亲等信息的术数。'),
(16,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '邵子神数', '邵子神数是北宋邵雍所创的一种术数，以河洛数理为基础，用于预测人生的各种信息。'),
(17,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '皇极数', '皇极数是一种高级的数术，与《皇极经世书》相关，可用于预测和推演事物发展。'),
(18,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '形势派', '形势在风水等领域指山川地理的外在形态，通过观察形势来判断环境的吉凶。'),
(19,'2025-04-22 15:16:00', '2025-04-22 15:16:00', NULL, 1, '理气派', '理气是风水理论的重要组成部分，通过阴阳五行、八卦等理论来分析和调整气场。');